import { useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { useProjectsContext } from './projects-context.js';
import { addTask, removeTask, measure } from './task-tree.js';
import { projectAreas } from './task-views.js';
import { ProjectHeader } from './project-tabs.js';
import { ProgressRing } from './progress-ring.js';
import { TaskForm } from './task-form.js';
import styles from './ui.module.css';

const STATUS_LABEL = { todo: 'Not started', active: 'In progress', done: 'Done' } as const;

/**
 * Project overview frame: a stacked bar showing how each area contributes to
 * the project total, then one card per area. Clicking an area opens its focus frame.
 */
export function ProjectOverviewPage() {
  const { projectId } = useParams();
  const { projects, loading, updateTasks, deleteProject } = useProjectsContext();
  const navigate = useNavigate();
  const [adding, setAdding] = useState(false);
  const project = projects.find((p) => p.id === projectId);

  if (loading) return <p className={styles.empty}>Loading…</p>;
  if (!project) return <NotFound />;

  const areas = projectAreas(project);
  const total = measure(project.tasks).total || 1;

  return (
    <div className={styles.page}>
      <ProjectHeader project={project} />

      {areas.length ? (
        <section className={styles.card}>
          <div className={styles.cardHead}>
            <h2 className={styles.sectionTitle}>Where the progress comes from</h2>
          </div>
          <div className={styles.stack} aria-hidden>
            {areas.map((a, i) => (
              <div key={a.task.id} className={styles.stackSeg} style={{ flexGrow: a.total, opacity: 0.35 + (0.65 * (areas.length - i)) / areas.length }}>
                <div className={styles.stackFill} style={{ width: `${a.percent}%`, background: project.color }} />
              </div>
            ))}
          </div>
          <ul className={styles.legend}>
            {areas.map((a) => (
              <li key={a.task.id}>
                <strong>{a.task.title}</strong> · {Math.round((a.done / total) * 100)}% of {a.weight}%
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <section>
        <div className={styles.cardHead}>
          <h2 className={styles.sectionTitle}>Areas</h2>
          {!adding ? <button className={styles.primaryBtn} onClick={() => setAdding(true)}>+ New area</button> : null}
        </div>
        {adding ? (
          <div className={styles.card}>
            <TaskForm
              placeholder="e.g. Gun system"
              submitLabel="Add area"
              onCancel={() => setAdding(false)}
              onSubmit={(v) => { updateTasks(project.id, (t) => addTask(t, null, v)); setAdding(false); }}
            />
          </div>
        ) : null}

        {areas.length ? (
          <div className={styles.areaGrid}>
            {areas.map((a) => (
              <article key={a.task.id} className={styles.areaCard}>
                <Link to={`/projects/${project.id}/areas/${a.task.id}`} className={styles.areaLink}>
                  <div className={styles.areaTop}>
                    <div className={styles.areaInfo}>
                      <span className={`${styles.badge} ${styles[`badge_${a.status}`]}`}>{STATUS_LABEL[a.status]}</span>
                      <h3>{a.task.title}</h3>
                      {a.task.description ? <p>{a.task.description}</p> : null}
                    </div>
                    <ProgressRing percent={a.percent} color={project.color} size={60} />
                  </div>
                  <div className={styles.areaFoot}>
                    <span>{a.done}/{a.total} tasks</span>
                    <span>{a.weight}% of project</span>
                  </div>
                </Link>
                <button
                  className={styles.cardDelete}
                  aria-label={`Delete ${a.task.title}`}
                  onClick={() => window.confirm(`Delete area "${a.task.title}" and all its tasks?`) && updateTasks(project.id, (t) => removeTask(t, a.task.id))}
                >
                  ✕
                </button>
              </article>
            ))}
          </div>
        ) : !adding ? (
          <div className={styles.card}><p className={styles.empty}>No areas yet. Areas are the big chunks of your project, like “Gun system” or “Movement”.</p></div>
        ) : null}
      </section>

      <div className={styles.dangerZone}>
        <button
          className={styles.dangerLink}
          onClick={() => {
            if (!window.confirm(`Delete project "${project.name}"?`)) return;
            deleteProject(project.id);
            navigate('/');
          }}
        >
          Delete project
        </button>
      </div>
    </div>
  );
}

/** Shown when a project or area id does not exist. */
export function NotFound() {
  return (
    <div className={styles.welcome}>
      <h1>Not found</h1>
      <p>This project or area doesn’t exist anymore.</p>
      <Link to="/" className={styles.primaryBtn}>Back to dashboard</Link>
    </div>
  );
}
